const r = await tools.exec_command({cmd:"pdftotext paper.pdf - | rg -n -i -C 3 "3\.17|deconvol|running|visual cortex|outside|interpol|0\.1|decimeter|frame rate|retinotop|spatial bin|gray space" | sed -n '1,500p'; python - <<'PY'
import numpy as np, os
# Build first-reference physical behavior inventory and compute stats / projected size.
root='/app/data'; E=np.load(root+'/beh/Imaging_Exp_info.npy',allow_pickle=True).item()
phys=[]; seen=set(); refs={}
for typ,rows in E.items():
 for r in rows:
  p=(r['mname'],r['datexp'],str(r['blk']))
  refs.setdefault(p,[]).append((typ,r))
  if p not in seen: seen.add(p); phys.append(p)
beh={}
for typ,rows in E.items():
 need=[r for r in rows if (r['mname'],r['datexp'],str(r['blk'])) not in beh]
 if not need: continue
 D=np.load(f'{root}/beh/Beh_{typ}.npy',allow_pickle=True).item()
 for r in rows:
  p=(r['mname'],r['datexp'],str(r['blk']))
  if p in beh: continue
  k='_'.join(p)+(('_'+r['stimtype']) if 'stimtype' in r else '')
  if k in D:
   d=D[k]; beh[p]={'n':int(d['ntrials']),'speed':np.asarray(d['run_pos'])[:,:40], 'walls':np.asarray(d['WallName'])}
 del D
print('physical',len(phys),'behavior',len(beh))
vals=np.concatenate([beh[p]['speed'].ravel() for p in phys])
print('speed n/min/q/max/nan',len(vals),np.nanmin(vals),np.nanquantile(vals,[.25,.5,.75]),np.nanmax(vals),np.isnan(vals).sum(),np.isinf(vals).sum())
size_all=size_vis=0; trials=0; regions={}
for p in phys:
 ia=np.load(f'{root}/retinotopy/{p[0]}_{p[1]}_trans.npz')['iarea']
 n=beh[p]['n']; trials+=n
 keep=(ia!=-1)&(ia!=7)
 size_all += len(ia)*n*40*4; size_vis += keep.sum()*n*40*4
 for x,c in zip(*np.unique(ia,return_counts=True)):regions[int(x)]=regions.get(int(x),0)+int(c)
print('trials',trials,'all GB',size_all/1e9,'visual GB',size_vis/1e9,'regions',regions)
print('walls',sorted(set(np.concatenate([beh[p]['walls'] for p in phys]).tolist())))
print('trial minmax',min(beh[p]['n'] for p in phys),max(beh[p]['n'] for p in phys))
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":20000}); text(r.output); if(r.session_id) text(`SESSION_ID=${r.session_id}`);

